function validateGroup(dto, group, rules) {
  const errors = [];
  for (const [field, rule] of Object.entries(rules)) {
    if (rule.groups && !rule.groups.includes(group)) continue;
    const v = dto[field];
    if (rule.notNull && (v === null || v === undefined)) errors.push(field + " 必填(" + group + ")");
  }
  return errors;
}
const rules = {
  id:   { groups: ["update"], notNull: true },
  name: { groups: ["insert", "update"], notNull: true },
};
